/**
 * Write ios/.xcode.env.updates during prebuild so Xcode archive bundling
 * (export:embed) inherits Metro heap settings on EAS and local Release builds.
 */
const fs = require("fs");
const path = require("path");
const { withDangerousMod } = require("@expo/config-plugins");

function withXcodeEnvUpdates(config) {
  return withDangerousMod(config, [
    "ios",
    async (cfg) => {
      const iosRoot = cfg.modRequest.platformProjectRoot;
      const updatesPath = path.join(iosRoot, ".xcode.env.updates");
      const content = [
        "# Generated by plugins/with-xcode-env-updates.js during expo prebuild.",
        "# Xcode archive runs export:embed here; Metro needs extra heap on EAS.",
        'export NODE_OPTIONS="${NODE_OPTIONS:---max-old-space-size=8192}"',
        'export METRO_NODE_OPTIONS="${METRO_NODE_OPTIONS:---max-old-space-size=8192}"',
        "",
      ].join("\n");
      fs.mkdirSync(iosRoot, { recursive: true });
      fs.writeFileSync(updatesPath, content);
      return cfg;
    },
  ]);
}

module.exports = withXcodeEnvUpdates;
